def main():
    assert len(SKILLS_CATALOG) == 100, f"Expected 100 skills, got {len(SKILLS_CATALOG)}"
    SKILLS_DIR.mkdir(parents=True, exist_ok=True)
    DESIGN_DIR.mkdir(parents=True, exist_ok=True)
    DATA_DIR.mkdir(parents=True, exist_ok=True)

    for idx, (name, desc, rule) in enumerate(SKILLS_CATALOG, start=1):
        sdir = SKILLS_DIR / name
        sdir.mkdir(parents=True, exist_ok=True)
        md = (
            f"---\n"
            f"name: {name}\n"
            f"description: \"{desc}\"\n"
            f"---\n\n"
            f"# {idx}. {name}\n\n"
            f"**Назначение:** {desc}\n\n"
            f"## Правила применения в проекте AETHERIA (UE 5.8)\n"
            f"- {rule}\n"
            f"- Проверяй интеграцию через `python Scripts/validate_ue5_project.py` и `python Scripts/verify_balance_and_loot.py`.\n"
        )
        (sdir / "SKILL.md").write_text(md, encoding="utf-8")

    # Design/GDD_Aetheria.md
    gdd = """# AETHERIA: Shards of the Chrono-Seal — Living Game Design Document (GDD)

## 1. Высокоуровневая концепция
- **Жанр:** Кооперативный dark-fantasy Action-RPG на **1–6 магов** (Unreal Engine 5.8 C++).
- **Визуальный эталон:** Мрачная фотореалистичная готика уровня *Diablo IV* (мокрые каменные плиты под Lumen, факельные жаровни 2200K против холодной луны 6800K, обсидиан, кованое железо, резные руны) + точечная кибер-кристаллическая эстетика Mind (`#00F5FF`, `#7B2FF7`) внутри живых заклинаний.
- **Ключевая фишка:** Система каста заклинаний по трём первозданным сферам `Q / W / E` в стиле Инвокера из Dota 2 с **двумя режимами в Настройках**:
  1. **Классический Инвокер (`InvokeThenAim`)**: `Q/W/E` → `R` в слот `D`/`F` → прицел на земле → `ЛКМ`.
  2. **Мгновенный каст (`InstantOnCombo`)**: 3-е нажатие комбинации (или `R`) мгновенно выпускает заклинание по курсору.
- **Передвижение:** `ПКМ` по земле с появлением **анимированных 3D-стрелочек стратегии** в точке клика (+ резерв на `Стрелки`), `Space` — рывок с окном неуязвимости `0.28с`.

## 2. Core & Meta Loop
1. **Боевая микро-петля (10–25 с):** Зарядка 3 сфер (`Q/W/E`) → применение заклинания (или синергии `Призма + Болид`, `Чёрная Дыра + Болид`, `Хроносфера + Цепная Молния`) → уничтожение паков мобов → сбор XP и Arcane Essence.
2. **Квестовая петля локации (5 актов, 40–60 мин в режиме Поход / 5–7 мин в Демо-Блиц):**
   - Акт I: Захват 3 рунных маяков.
   - Акт II: Защита центрального Эфирного Обелиска (0% → 100%).
   - Акт III: Разрушение 4 экранированных Пилонов Хранителя.
   - Акт IV: Разгром Элитного Легиона Разлома.
   - Акт V: Битва с уникальным Боссом-Хранителем → Выпадение реликвии и Первозданного Осколка → Астральный Портал в следующую локацию.
3. **Мета-петля (`UAetheriaSaveGame`):** Повышение уровня мага (`XP(L) = 100 * L^1.65`), накопление Arcane Essence, сохранение реликвий и открытых локаций.

## 3. Гримуар-книга (`Tab`)
Открывается как двустраничный иллюстрированный фолиант в кожаном переплёте: слева — художественная гравюра заклинания и печать `[Q/W/E]`, справа — лор, формулы урона/КД/маны, синергии и кнопка зарядки сфер. Перелистывается кнопками `◄ / ►`, стрелками клавиатуры, колесом мыши и закладками `I..X`.
"""
    (DESIGN_DIR / "GDD_Aetheria.md").write_text(gdd, encoding="utf-8")

    # Design/Worldbuilding_Bible.md
    bible = """# Worldbuilding Bible — Хроника Раскола Хроно-Печати

Тысячу лет Цитадель Эфира удерживала три первозданные силы — **Игнис (`Q`)**, **Темпест (`W`)** и **Гравитон (`E`)** — в равновесии Хроно-Печати. Когда Архимаг Раскола разбил Печать на 10 Осколков, каждый осколок породил искажённый биом на границах реальности:
1. **Расколотый Бастион Эфира** — внешнее святилище мокрых каменных плит и тлеющих жаровен.
2. **Пепельная Кальдера Игниса** — базальтовые разломы с пульсирующей магмой.
3. **Кристальный Ледник Хроноса** — застывшие в вечном льду сланцевые шпили.
4. **Гравитационные Сады Пустоты** — перевёрнутые парящие обелиски.
5. **Грозовой Некрополь Бурь** — медные шпили, притягивающие молнии.
6. **Зеркальный Лабиринт Миражей** — преломляющие магию призмы.
7. **Бездна Затонувшего Астролябия** — затопленный звёздный механизм.
8. **Обсидиановая Кузня Титанов** — наковальни звёздного металла.
9. **Храм Остановившегося Времени** — руины, где секунды застыли в камне.
10. **Сердце Расколотой Хроно-Печати** — тронный алтарь Первозданного Архимага, использующего те же сферы `Q/W/E`.
"""
    (DESIGN_DIR / "Worldbuilding_Bible.md").write_text(bible, encoding="utf-8")

    # Data/LootTables.json
    loot = {
        "version": 1,
        "rarities": [
            {"id": "Common", "name_ru": "Обычная", "weight": 55, "power_mult": 1.0, "color": "#9AA0AC"},
            {"id": "Rare", "name_ru": "Редкая", "weight": 26, "power_mult": 1.18, "color": "#1E90FF"},
            {"id": "Epic", "name_ru": "Эпическая", "weight": 13, "power_mult": 1.38, "color": "#9B5DE5"},
            {"id": "Mythic", "name_ru": "Мифическая", "weight": 5, "power_mult": 1.65, "color": "#FF6820"},
            {"id": "Ancient", "name_ru": "Древняя Реликвия", "weight": 1, "power_mult": 2.0, "color": "#E3B341"}
        ],
        "pity_timer_kills": 18,
        "relics": [
            {"id": "ember_heart", "name": "Угольное Сердце Кальдеры", "bonus": "+12% урона Игниса (Q)"},
            {"id": "chrono_astrolabe", "name": "Малый Астролябий Вечности", "bonus": "-10% перезарядки Хроносферы"},
            {"id": "singularity_seal", "name": "Печать Горизонта Событий", "bonus": "+15% радиус Чёрной Дыры"},
            {"id": "prism_monocle", "name": "Хрустальная Призма Лабиринта", "bonus": "+18% урона от расщепления"},
            {"id": "archon_crown", "name": "Осколок Короны Архимага", "bonus": "+25 Макс. Маны и +12% ко всем стихиям"}
        ]
    }
    (DATA_DIR / "LootTables.json").write_text(json.dumps(loot, ensure_ascii=False, indent=2), encoding="utf-8")
    print("Installed 100 workspace skills in .agents/skills + Design/GDD_Aetheria.md + Design/Worldbuilding_Bible.md + Data/LootTables.json")

if __name__ == "__main__":
    main()
